/** FlightGear's messages_config_memo */
export function configMemo(F: Fwc): void {
  const { g, s, R, M, V, t, eq } = F;
  V.phaseVarMemo = g("ECAM/warning-phase");
  if (
    eq(g("controls/flight/flaps-input"), 0) ||
    eq(g("controls/flight/flaps-input"), 4) ||
    !eq(g("controls/flight/speedbrake"), 0) ||
    g("systems/fcs/stabilizer/final-deg") > 1.75 ||
    g("systems/fcs/stabilizer/final-deg") < -3.65 ||
    g("systems/fcs/rudder/trim-cmd-deg") < -3.55 ||
    g("systems/fcs/rudder/trim-cmd-deg") > 3.55
  ) {
    s("ECAM/to-config-normal", 0);
  } else {
    s("ECAM/to-config-normal", 1);
  }
  if (t(g("ECAM/to-config-test")) && (eq(V.phaseVarMemo, 1) || eq(V.phaseVarMemo, 2) || eq(V.phaseVarMemo, 9))) {
    s("ECAM/to-config-set", 1);
  } else {
    s("ECAM/to-config-set", 0);
  }
  if (!t(g("ECAM/to-config-normal")) || eq(V.phaseVarMemo, 6)) {
    s("ECAM/to-config-reset", 1);
  } else {
    s("ECAM/to-config-reset", 0);
  }
  if (eq(g("controls/autobrake/mode"), 3)) {
    M.toMemoLine1.msg = "T.O AUTO BRK MAX";
    M.toMemoLine1.colour = "g";
  } else {
    M.toMemoLine1.msg = "T.O AUTO BRK.....MAX";
    M.toMemoLine1.colour = "c";
  }
  if (t(g("controls/lighting/seatbelt-sign")) && t(g("controls/lighting/no-smoking-sign"))) {
    M.toMemoLine2.msg = "    SIGNS ON";
    M.toMemoLine2.colour = "g";
  } else {
    M.toMemoLine2.msg = "    SIGNS.........ON";
    M.toMemoLine2.colour = "c";
  }
  if (t(g("controls/flight/speedbrake-arm"))) {
    M.toMemoLine3.msg = "    SPLRS ARM";
    M.toMemoLine3.colour = "g";
  } else {
    M.toMemoLine3.msg = "    SPLRS........ARM";
    M.toMemoLine3.colour = "c";
  }
  if (g("controls/flight/flaps-pos") > 0 && g("controls/flight/flaps-pos") < 5) {
    M.toMemoLine4.msg = "    FLAPS T.O";
    M.toMemoLine4.colour = "g";
  } else {
    M.toMemoLine4.msg = "    FLAPS........T.O";
    M.toMemoLine4.colour = "c";
  }
  if (t(g("ECAM/to-config-flipflop")) && t(g("ECAM/to-config-normal"))) {
    M.toMemoLine5.msg = "    T.O CONFIG NORMAL";
    M.toMemoLine5.colour = "g";
  } else {
    M.toMemoLine5.msg = "    T.O CONFIG..TEST";
    M.toMemoLine5.colour = "c";
  }
  if (t(g("ECAM/to-config-test")) && (eq(V.phaseVarMemo, 2) || eq(V.phaseVarMemo, 9))) {
    s("ECAM/to-memo-set", 1);
  } else {
    s("ECAM/to-memo-set", 0);
  }
  if (eq(V.phaseVarMemo, 1) || eq(V.phaseVarMemo, 3) || eq(V.phaseVarMemo, 6) || eq(V.phaseVarMemo, 10)) {
    s("ECAM/to-memo-reset", 1);
  } else {
    s("ECAM/to-memo-reset", 0);
  }
  if (
    (eq(V.phaseVarMemo, 2) && !eq(g("ECAM/engine-start-time"), 0) && g("ECAM/engine-start-time") + 120 < g("sim/time/elapsed-sec")) ||
    t(g("ECAM/to-memo-flipflop"))
  ) {
    M.toMemoLine1.active = 1;
    M.toMemoLine2.active = 1;
    M.toMemoLine3.active = 1;
    M.toMemoLine4.active = 1;
    M.toMemoLine5.active = 1;
  } else {
    R(M.toMemoLine1);
    R(M.toMemoLine2);
    R(M.toMemoLine3);
    R(M.toMemoLine4);
    R(M.toMemoLine5);
  }
  if (eq(g("systems/gear/all-norm"), 1)) {
    M.ldgMemoLine1.msg = "LDG LDG GEAR DN";
    M.ldgMemoLine1.colour = "g";
  } else {
    M.ldgMemoLine1.msg = "LDG LDG GEAR......DN";
    M.ldgMemoLine1.colour = "c";
  }
  if (t(g("controls/lighting/seatbelt-sign")) && t(g("controls/lighting/no-smoking-sign"))) {
    M.ldgMemoLine2.msg = "    SIGNS ON";
    M.ldgMemoLine2.colour = "g";
  } else {
    M.ldgMemoLine2.msg = "    SIGNS.........ON";
    M.ldgMemoLine2.colour = "c";
  }
  if (t(g("controls/flight/speedbrake-arm"))) {
    M.ldgMemoLine3.msg = "    SPLRS ARM";
    M.ldgMemoLine3.colour = "g";
  } else {
    M.ldgMemoLine3.msg = "    SPLRS........ARM";
    M.ldgMemoLine3.colour = "c";
  }
  if (eq(g("it-fbw/law"), 1) || t(g("instrumentation/mk-viii/inputs/discretes/momentary-flap-3-override"))) {
    if (eq(g("controls/flight/flaps-pos"), 4)) {
      M.ldgMemoLine4.msg = "    FLAPS CONF 3";
      M.ldgMemoLine4.colour = "g";
    } else {
      M.ldgMemoLine4.msg = "    FLAPS.....CONF 3";
      M.ldgMemoLine4.colour = "c";
    }
  } else if (eq(g("controls/flight/flaps-pos"), 5)) {
    M.ldgMemoLine4.msg = "    FLAPS FULL";
    M.ldgMemoLine4.colour = "g";
  } else {
    M.ldgMemoLine4.msg = "    FLAPS.......FULL";
    M.ldgMemoLine4.colour = "c";
  }
  if (V.gear_agl_cur < 2000) {
    s("ECAM/ldg-memo-set", 1);
  } else {
    s("ECAM/ldg-memo-set", 0);
  }
  if (V.gear_agl_cur > 2200) {
    s("ECAM/ldg-memo-reset", 1);
  } else {
    s("ECAM/ldg-memo-reset", 0);
  }
  if (V.gear_agl_cur > 2200) {
    s("ECAM/ldg-memo-2200-set", 1);
  } else {
    s("ECAM/ldg-memo-2200-set", 0);
  }
  if (!eq(V.phaseVarMemo, 6) && !eq(V.phaseVarMemo, 7) && !eq(V.phaseVarMemo, 8)) {
    s("ECAM/ldg-memo-2200-reset", 1);
  } else {
    s("ECAM/ldg-memo-2200-reset", 0);
  }
  if (
    (eq(V.phaseVarMemo, 6) && t(g("ECAM/ldg-memo-flipflop")) && t(g("ECAM/ldg-memo-2200-flipflop"))) ||
    eq(V.phaseVarMemo, 7) ||
    eq(V.phaseVarMemo, 8)
  ) {
    M.ldgMemoLine1.active = 1;
    M.ldgMemoLine2.active = 1;
    M.ldgMemoLine3.active = 1;
    M.ldgMemoLine4.active = 1;
  } else {
    R(M.ldgMemoLine1);
    R(M.ldgMemoLine2);
    R(M.ldgMemoLine3);
    R(M.ldgMemoLine4);
  }
}

/** FlightGear's messages_memo */
export function memo(F: Fwc): void {
  const { g, s, M, V, t, eq, cat, max, round, after } = F;
  V.phaseVarMemo2 = g("ECAM/warning-phase");
  if (eq(g("services/fuel-truck/connect"), 1) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    M.refuelg.active = 1;
  } else {
    M.refuelg.active = 0;
  }
  if (
    eq(g("@systems.ADIRS.ADIRunits[0].inAlign"), 1) ||
    eq(g("@systems.ADIRS.ADIRunits[1].inAlign"), 1) ||
    eq(g("@systems.ADIRS.ADIRunits[2].inAlign"), 1)
  ) {
    s("ECAM/irs-in-align", 1);
  } else {
    s("ECAM/irs-in-align", 0);
  }
  if (
    (eq(V.phaseVarMemo2, 1) || eq(V.phaseVarMemo2, 2)) &&
    !eq(M.toMemoLine1.active, 1) &&
    !eq(M.ldgMemoLine1.active, 1) &&
    (eq(g("@systems.ADIRS.ADIRunits[0].inAlign"), 1) ||
      eq(g("@systems.ADIRS.ADIRunits[1].inAlign"), 1) ||
      eq(g("@systems.ADIRS.ADIRunits[2].inAlign"), 1))
  ) {
    M.irs_in_align.active = 1;
    if (t(g("ECAM/phases/phase-calculation/engine-1-or-2-running"))) {
      M.irs_in_align.colour = "a";
    } else {
      M.irs_in_align.colour = "g";
    }
    V.timeNow = g("sim/time/elapsed-sec");
    V.numberMinutes = round(
      max(
        g("@systems.ADIRS.ADIRunits[0]._alignTime") - V.timeNow,
        g("@systems.ADIRS.ADIRunits[1]._alignTime") - V.timeNow,
        g("@systems.ADIRS.ADIRunits[2]._alignTime") - V.timeNow,
      ) / 60,
    );
    if (V.numberMinutes >= 7) {
      M.irs_in_align.msg = "IRS IN ALIGN > 7 MN";
    } else if (V.numberMinutes >= 1) {
      M.irs_in_align.msg = cat(cat("IRS IN ALIGN ", V.numberMinutes), " MN");
    } else {
      M.irs_in_align.msg = "IRS IN ALIGN";
    }
  } else if (t(M.irs_in_align.active) && !t(V.timer10secIRS)) {
    V.timer10secIRS = 1;
    M.irs_in_align.msg = "IRS ALIGNED";
    after(10, () => {
      M.irs_in_align.active = 0;
      M.irs_in_align.msg = "IRS IN ALIGN";
      V.timer10secIRS = 0;
    });
  } else if (!t(V.timer10secIRS)) {
    M.irs_in_align.active = 0;
    M.irs_in_align.msg = "IRS IN ALIGN";
  }
  if (eq(g("controls/flight/speedbrake-arm"), 1) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    M.gnd_splrs.active = 1;
  } else {
    M.gnd_splrs.active = 0;
  }
  if (t(g("controls/lighting/seatbelt-sign")) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    M.seatbelts.active = 1;
  } else {
    M.seatbelts.active = 0;
  }
  if (t(g("controls/lighting/no-smoking-sign")) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    M.nosmoke.active = 1;
  } else {
    M.nosmoke.active = 0;
  }
  if (!t(g("controls/lighting/strobe")) && !t(g("gear/gear[1]/wow")) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    M.strobe_lt_off.active = 1;
  } else {
    M.strobe_lt_off.active = 0;
  }
  if (
    eq(g("systems/fuel/valves/outer-inner-transfer-valve-1"), 1) ||
    (eq(g("systems/fuel/valves/outer-inner-transfer-valve-2"), 1) && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1))
  ) {
    M.outr_tk_fuel_xfrd.active = 1;
  } else {
    M.outr_tk_fuel_xfrd.active = 0;
  }
  if (g("consumables/fuel/total-fuel-lbs") < 6613 && !eq(M.toMemoLine1.active, 1) && !eq(M.ldgMemoLine1.active, 1)) {
    if (t(g("systems/acconfig/options/weight-kgs"))) {
      M.fob_3T.active = 1;
      M.fob_66L.active = 0;
    } else {
      M.fob_3T.active = 0;
      M.fob_66L.active = 1;
    }
  } else {
    M.fob_3T.active = 0;
    M.fob_66L.active = 0;
  }
  if (
    t(g("instrumentation/mk-viii/inputs/discretes/momentary-flap-all-override")) &&
    !eq(M.toMemoLine1.active, 1) &&
    !eq(M.ldgMemoLine1.active, 1)
  ) {
    M.gpws_flap_mode_off.active = 1;
  } else {
    M.gpws_flap_mode_off.active = 0;
  }
  if (
    !t(g("@fmgc.FMGCInternal.flightNumSet")) &&
    !eq(M.toMemoLine1.active, 1) &&
    !eq(M.ldgMemoLine1.active, 1) &&
    (V.phaseVarMemo2 <= 2 || eq(V.phaseVarMemo2, 6) || V.phaseVarMemo2 >= 9)
  ) {
    M.company_datalink_stby.active = 1;
  } else {
    M.company_datalink_stby.active = 0;
  }
}

